/** In-memory private storage; a lost acknowledgement keeps the object out of sight until `land()`. */
class Storage implements ImportObjectStorage {
    objects = new Map<string, { target: ImportObjectTarget; identity: ImportObjectIdentity }>(); hidden = new Map<string, { target: ImportObjectTarget; identity: ImportObjectIdentity }>(); loseNextPut = false;
    async head(target: ImportObjectTarget) { return this.objects.get(`${target.bucket}/${target.key}`)?.identity ?? null; }
    async put(target: ImportObjectTarget) {
        const identity = { etag: '"stage-etag"', versionId: 'stage-version' };
        if (this.loseNextPut) { this.loseNextPut = false; this.hidden.set(`${target.bucket}/${target.key}`, { target, identity }); throw new Error('synthetic lost acknowledgement'); }
        this.objects.set(`${target.bucket}/${target.key}`, { target, identity }); return identity;
    }
    land() { for (const [key, value] of this.hidden) this.objects.set(key, value); this.hidden.clear(); }
    async copy(_source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) { const identity = { etag: '"canonical-etag"', versionId: 'canonical-version' }; this.objects.set(`${target.bucket}/${target.key}`, { target, identity }); return identity; }
    async delete(target: ImportObjectTarget & ImportObjectIdentity) { this.objects.delete(`${target.bucket}/${target.key}`); }
}
