/** An import whose files are already confirmed with the given evidence, written directly (no trigger runs). */
async function seeded(count: number, tags: (index: number) => ImportEmbeddedTagsV2, options: { folder?: boolean } = {}) {
    const item = await project(Array.from({ length: count }, (_unused, index) => options.folder === false ? `0${index} Secret File ${index}.wav` : `Disc 1/0${index} Secret File ${index}.wav`));
    const now = new Date();
    const assets = item.manifest.files.map((file, index) => {
        const operationId = randomUUID();
        return { slotId: file.slotId, operationId, actorId: by, bucket: 'synthetic-private-imports', key: `imports/${item.id}/${file.slotId}/${operationId}`, sha256: randomUUID().replace(/-/g, '').repeat(2),
            byteLength: 10, contentType: 'audio/wav', filename: file.filename, state: 'ready' as const, versionId: 'stage-version', etag: '"stage-etag"', updatedAt: now, leaseOwner: null, leaseUntil: null,
            transferDeadline: null, failureConfirmedAt: null, duration: '0:01', format: 'wav', representation: null, tags: tags(index), automatedAt: now,
            recovery: { operationId, expectedRevision: 1, kind: 'upload' as const, actorId: by } };
    });
    await projects().updateOne({ _id: new ObjectId(item.id) }, { $set: { media: { assets } } });
    return item.id;
}

