/** Holds the first release search in flight until `release()`, so other work runs while a step's request is outstanding. */
function holdFirstSearch(client: MusicBrainzClient) {
    let release!: () => void, entered!: () => void, holding = true;
    const held = new Promise<void>(resolve => { release = resolve; }), inFlight = new Promise<void>(resolve => { entered = resolve; });
    const musicBrainz: MusicBrainzClient = { ...client, async searchReleases(query, options) {
        if (holding) { holding = false; entered(); await held; }
        return client.searchReleases(query, options);
    } };
    return { musicBrainz, inFlight, release };
}

