    assert.deepEqual(submitted.queries.map(query => query.kind === 'musicBrainzRecordingSearch' ? query.query : null), [{ recording: 'Typed Song' }]);
    // The rerun is automatic, so it waits for the gate even while it is held elsewhere, rather than reporting busy.
    const modes: string[] = [];
