test('a failed fence write aborts the step and the run resumes, and a trigger racing a publication lock queues nothing', async t => {
    const id = await seeded(1, () => v2({ album: 'Synthetic Album', albumArtists: ['Synthetic Ensemble'] }));
    await requestAutomaticMetadataLookup(by, id, 'upload');
    let failures = 1; const original = Collection.prototype.updateOne;
    const mocked = t.mock.method(Collection.prototype, 'updateOne', async function (this: Collection, ...args: unknown[]) {
        if (this.collectionName === 'adminAlbumImports' && failures > 0 && JSON.stringify(args[1]).includes('lookupGate')) { failures--; throw new Error('synthetic fence failure'); }
        return (original as (...values: unknown[]) => unknown).apply(this, args);
    });
    const client = fixtureClient([searchAnswer(albumQuery, []), searchAnswer({ release: 'Synthetic Album' }, [])]);
    await assert.rejects(runMetadataLookupOnce({ musicBrainz: client.musicBrainz }), /synthetic fence failure/);
    const unchanged = (await lookup(id))!;
    assert.deepEqual([unchanged.state, unchanged.queryIndex, (await stored(id)).lookupGate!.fence, client.requests.length], ['queued', 0, 1, 0]);
    assert.equal(await runMetadataLookupOnce({ musicBrainz: client.musicBrainz }), false, 'the lease still holds');
    await drain({ musicBrainz: client.musicBrainz, now: () => later(181_000) });
    assert.deepEqual([(await lookup(id))!.state, (await stored(id)).lookupGate!.fence], ['complete', 3]);
    mocked.mock.restore();

    const racing = await seeded(1, () => v2({ title: 'Synthetic Song' }));
    const arm = onNextProjectRead(t, () => projects().updateOne({ _id: new ObjectId(racing) }, { $set: { 'media.publication': preparingPublication() } }));
    arm();
    assert.equal((await requestAutomaticMetadataLookup(by, racing, 'upload')).reason, 'closed');
    assert.deepEqual([await lookup(racing), (await stored(racing)).lookupGate], [null, undefined]);
});

